import sys

def main():
    n = int(sys.stdin.read().split()[0])
    s = [0] * (n + 1)
    for d in range(1, n // 2 + 1):
        for m in range(2 * d, n + 1, d):
            s[m] += d
    res = [k for k in range(2, n + 1) if s[k] == k]
    print(' '.join(map(str, res)) if res else '-1')

main()

